        var cx = w * 0.5;
        var cy = h - (cameraMode === 2 ? 120 : 82);
        var cw = cameraMode === 2 ? 126 : 164;
        var ch = cameraMode === 2 ? 68 : 84;

        ctx.save();
        ctx.translate(cx, cy);
        ctx.rotate(carTilt * 0.08);

        // Ground shadow
